CREATE TABLE IF NOT EXISTS done (date TEXT NOT NULL, item_id TEXT NOT NULL, value INTEGER NOT NULL DEFAULT 1, done_at TEXT NOT NULL, PRIMARY KEY (date, item_id));
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, workout TEXT, duration_s INTEGER, distance_m INTEGER, hr_avg INTEGER, hr_max INTEGER, cadence INTEGER, test_value TEXT, rpe INTEGER, pain INTEGER, pain_where TEXT, pain_side TEXT, pain_when TEXT, pain_gone TEXT, note TEXT, source TEXT DEFAULT 'app', strava_id TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS runs_date ON runs(date);
CREATE TABLE IF NOT EXISTS checks (date TEXT PRIMARY KEY, squat INTEGER, shin INTEGER, hop INTEGER, bone INTEGER DEFAULT 0, limp INTEGER DEFAULT 0, sick INTEGER DEFAULT 0, rhr INTEGER, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, ex_id TEXT NOT NULL, value TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS overrides (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, field TEXT NOT NULL, value TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS overrides_date ON overrides(date);
CREATE TABLE IF NOT EXISTS coach_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, text TEXT NOT NULL, author TEXT DEFAULT 'claude', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subs (endpoint TEXT PRIMARY KEY, keys_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_log (key TEXT PRIMARY KEY, sent_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (ip TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
